import{enemyRewardIds}from'./path-combat.js';
import{elementalAttack}from'./elemental-attacks.js';
import{deviceReport,VISUAL_CHECKS}from'./device-report.js';
import{bindStick,bindActionButton}from'./touch-stick.js';
import{GRAPHICS_KEY,QUALITY,graphicsSettings,applyGraphics}from'./render-quality.js';
import{approachGuidance,practiceGoal}from'./trail-guidance.js';
import{GameAudio}from'./game-audio.js';
import{PARTNERS,partnerInfo,partnerPortrait,upgradePartners,choosePartner}from'./partners.js';
import{trialHint,crystalState}from'./path-trials-layout.js';
import{enemyHint}from'./path-combat.js';import{TrailWorld}from'./trail-world.js';import{mechanismMarkup}from'./world-mechanisms.js';import{TrailNavigator}from'./trail-nav.js';import{TRAILS,collectCoin,equipTrail,upgradeTraversalSave,travelState}from'./traversal.js';import{AREAS,validSave as validLegacy}from'./core.js';import{ACTIVITIES,TASK_TYPES,STORE,LEGACY_STORE,activity,freshJourney,freshSave,required,progress,maximum,unlocked,ready,guardianReady,freshExpedition,expedition,currentType,chooseBranch,milestone,finishExpedition,winGuardian,restart,migrate,validSave,encode}from'./expedition.js';import{activeNode,approachPoint,CHAPTERS,CHAPTER_LENGTH}from'./trail-layout.js';import{makeTask,actTask,taskFraction,taskHint}from'./trail-tasks.js';import{evolutionAudio}from'./evolution-audio.js';import{floatText,burst,flyCoins,bump,flash,haptic,HAPTICS}from'./game-feel.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let save=freshSave(),units=[],world,nav,screen='home',modal=false,locked=false,task=null,resultCard=false,lastSnapshot=0,toastTimer,nearId='',autoOpenAfter=0,audioContext,evoState,evoStop,speechSupported='speechSynthesis'in window,feedbackText='',pendingCompletion=null;
const deviceChecks={};const gameAudio=new GameAudio();let graphics=graphicsSettings(null);try{graphics=graphicsSettings(JSON.parse(localStorage.getItem(GRAPHICS_KEY)||'null'));}catch{}
const partner=()=>partnerInfo(save.partner);
const unit=()=>units.find(u=>u.id===save.selected)||units[0],journey=()=>save.journeys[save.selected]??=(freshJourney()),state=()=>expedition(journey(),save.selected,save.area);
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('toast-shown');document.body.classList.add('hud-notice');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('#toast').classList.remove('toast-shown');document.body.classList.remove('hud-notice');},3600);}
function snapshot(){if(nav&&nav.state===state()){state().position={...nav.player};state().heading=nav.heading;}}
function persist(){snapshot();try{localStorage.setItem(STORE,encode(save));$('#save-indicator').textContent='Checkpoint saved on this device';return true;}catch{$('#save-indicator').textContent='Not saved · export a backup';toast('This browser could not save. Export a backup from the journey journal.');return false;}}
function soundUpdate(){gameAudio.setMuted(save.muted);if(save.muted)gameAudio.silence();if(world){world.partner=partner().id;world.elementColor=partner().color;world.trailColor=save.wallet?.equipped==='air'?partner().color:TRAILS.find(t=>t.id===save.wallet?.equipped)?.color||partner().color;}$('#sound-button').style.opacity=save.muted?'.5':'1';$('#sound-button').setAttribute('aria-label',save.muted?'Enable sound':'Mute sound');}
function cue(kind='place'){if(save.muted)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();gameAudio.attach(audioContext);audioContext.resume()?.catch?.(()=>{});gameAudio.play(kind);}catch{}}
function tone(ok=true){cue(ok?'place':'wrong');}
function showModal(title,html){world.measurementPhase=null;modal=true;world.paused=true;world.setInput(0,0);$('#modal-layer').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${esc(title)}</h2><button class="close" data-do="close-modal" aria-label="Close">×</button></div>${html}</section></div>`;$('.modal .close')?.focus();}
function closeModal(){modal=false;$('#modal-layer').innerHTML='';if(world)world.paused=false;}
let coinsInFlight=0,lastTap=null,lastDamage=0;
const coinText=()=>Math.max(0,(save.wallet?.balance||0)-coinsInFlight);
function showCoins(){const c=$('#coin-count');if(c)c.textContent=coinText();}
function buzz(pattern){return haptic(pattern,{enabled:save.haptics!==false});}
// Coins fly from where they were earned to the counter, which ticks up as each arrives.
function rewardCoins(value,from){if(!value)return;const target=$('#coin-count');if(!target||!from||document.hidden){showCoins();return;}coinsInFlight+=value;showCoins();const n=Math.min(value,12);let left=value;flyCoins(from,target,n,i=>{const add=i===n-1?left:Math.min(left,Math.max(1,Math.floor(value/n)));left-=add;coinsInFlight=Math.max(0,coinsInFlight-add);showCoins();bump(target);cue('coinTick');});}
function feelDamage(r){lastDamage=Date.now();const final=r.hp<=0,p=world?.screenPoint?.({x:r.x,y:1.35,z:r.z});if(p)floatText(p.x,p.y,String(Math.ceil(100/Math.max(1,r.maxHp))),final?'crit':'damage');world?.juice?.hitstop(final?85:65);world?.juice?.shake(final?.42:.26);buzz(final?HAPTICS.crit:HAPTICS.hit);}
function feelImpact(p,hit){if(hit&&Date.now()-lastDamage<50)return;const s=world?.screenPoint?.({x:p.x,y:(p.y||.6)+.5,z:p.z});if(hit){if(s)floatText(s.x,s.y,'Crack!','crack');world?.juice?.hitstop(60);world?.juice?.shake(.22);buzz(HAPTICS.hit);}else{if(s)floatText(s.x,s.y,'Blocked','blocked');world?.juice?.shake(.08);}}
function feelHurt(){world?.juice?.hitstop(90);world?.juice?.shake(.5);flash('hurt');buzz(HAPTICS.hurt);}
function configureTravel(){nav.partner=partner().id;nav.enableTraversal(save.mode,{heading:()=>world?.controlHeading??nav.heading,face:heading=>{if(world){world.controlHeading=heading;if(world.locomotion)world.locomotion.heading=heading;}},combatSave:()=>persist(),trialSave:()=>persist(),trialReward:s=>{let gained=0;for(let i=0;i<2;i++)gained+=collectCoin(save,state(),{id:s.id+':crystal-reward:'+i});persist();const node=s.trial?.nodes?.[1];rewardCoins(gained,node&&world?.screenPoint?.({x:node.x,y:1,z:node.z}));toast('Crystal barrier cleared · coins saved.');},impact:(p,hit)=>{world?.combatEffect?.(p,hit);cue(hit?'impact':'wrong');feelImpact(p,hit);},damaged:r=>feelDamage(r),projectile:p=>cue({air:'castAir',fire:'castFire',nature:'castNature',water:'castWater'}[p.element]),projectileImpact:(p,kind)=>world?.elementalFX?.impact(p,kind),attack:a=>{world?.attackEffect?.(a);if(world?.locomotion)world.locomotion.heading=a.heading;},defeat:r=>{cue('reward');let gained=0;for(const id of enemyRewardIds(r))gained+=collectCoin(save,state(),{id});persist();const at=world?.screenPoint?.({x:r.x,y:1,z:r.z});if(at)burst(at.x,at.y,{color:partner().color,count:18,spread:90});buzz(HAPTICS.reward);rewardCoins(gained,at);toast(r.spec.name+(nav.combat.remaining?' yields! '+nav.combat.remaining+' more in this group · ':' yields! Path opened · ')+(save.mode==='challenge'?10:5)+' coins saved.');},coin:coin=>{const value=collectCoin(save,state(),coin);if(value){persist();cue('coin');world?.coinEffect?.(coin);rewardCoins(value,world?.screenPoint?.(coin));}},retry:reason=>{cue('impact');feelHurt();persist();world?.retryEffect?.(reason);const thumb=$('#joystick-thumb');if(thumb)thumb.style.transform='';toast(reason==='boulder'?'A rolling boulder! Watch the amber lane and wait in an alcove.':reason==='thorns'?'Watch the green gap. Your coins and English progress are safe.':reason==='leaf-slam'?'Leaf slam! Sidestep the marked sector, then circle behind.':reason==='spore-ring'?'Spore ring! Jump as the ring approaches. Coins and English progress are safe.':reason==='charge'?'Caught by the charge! Try a sidestep or jump. Coins and English progress are safe.':reason==='poison'?'Poison spores! Back to your safe spot.':'Missed the landing. Aim for a flat stone top; jump near its edge. Your coins and English work are safe.');},checkpoint:()=>persist(),notice:text=>toast(text)});}
function syncWorld(){world.partner=partner().id;world.elementColor=partner().color;const e=state();nav.state=e;configureTravel();nav.setLevel(journey().level);nav.restore(e.position);nav.heading=e.heading;world.viewRig.yaw=e.heading;world.viewRig.inputYaw=null;world.setArea(save.area);world.trailColor=save.wallet?.equipped==='air'?partner().color:TRAILS.find(t=>t.id===save.wallet?.equipped)?.color||partner().color;if(world.locomotion)world.locomotion.heading=e.heading;}
async function home(){if(!world)return;pendingCompletion=null;screen='home';task=null;resultCard=false;locked=false;world.paused=false;document.body.classList.remove('playing','cinematic','in-task','guardian-choice');$('#task-layer').innerHTML='';$('#world-labels').innerHTML='';world.setView(true);renderHome();}
function renderHome(){const j=journey(),u=unit(),e=state(),cp=e.checkpoint;$('#ui').innerHTML=`<div class="home-layout"><section class="setup"><div class="eyebrow">THE WINDWARD TRAILS</div><h1>One path.<br>A new discovery.</h1><p class="intro">Explore a living 3D valley with your creature partner. Choose your trail, help its creatures and grow through English.</p><div class="partner-choices" role="group" aria-label="Choose your creature">${PARTNERS.map(p=>`<button data-do="partner" data-partner="${p.id}" class="${p.id===partner().id?'selected':''}" aria-pressed="${p.id===partner().id}"><img src="${partnerPortrait(p.id,j.level)}" alt=""><span><strong>${p.name}</strong><small>${p.element} · Form ${j.level}</small></span></button>`).join('')}</div><div class="field-label"><span>Your lesson</span><span>44 unit journeys</span></div><button class="lesson-button" data-do="lessons"><span><strong>${esc(u.title)}</strong><small>GRADE ${u.grade} · ${esc(u.cefr)} · LEVEL ${j.level}</small></span><span>↗</span></button><div class="field-label"><span>Your arena</span><span>${unlocked(j)+1} / 3 unlocked</span></div><div class="area-options">${AREAS.map((a,i)=>`<button class="area-card ${i===save.area?'selected':''}" data-do="area" data-area="${i}" aria-pressed="${i===save.area}"><span class="area-number">0${i+1}</span>${i>unlocked(j)?'<span class="lock">LOCKED</span>':''}<strong>${a.name}</strong><small>${i>unlocked(j)?'Defeat the previous guardian':a.levels}</small></button>`).join('')}</div><div class="field-label"><span>Expedition mode</span><button class="text-button" data-do="help">How to play</button></div><div class="segmented">${['relaxed','challenge'].map(m=>`<button data-do="mode" data-mode="${m}" class="${m===save.mode?'selected':''}" aria-pressed="${m===save.mode}">${m==='relaxed'?'Relaxed':'Challenge'}</button>`).join('')}</div><p class="mode-help">${save.mode==='relaxed'?'Assisted edge jumps, gentler hazards and optional hints.':'Manual jumps, stronger hazards and double coins. Reading stays untimed.'}</p><div class="resume-note"><span>✧ ${cp?'MILESTONE '+e.index+' / 20 SAVED':e.index?'TRAIL PROGRESS SAVED':'A FRESH TRAIL'}</span><p>${j.completed?'Unit journey complete. Choose a new lesson or restart this journey.':e.active?'An unfinished activity is ready to resume.':cp?`${esc(activity(cp.type)?.object)} restored. Continue from your saved position.`:'Every expedition includes all 20 language activities.'}</p></div><button class="primary wide" data-do="${j.completed?'lessons':'enter'}"><span>${j.completed?'Choose a new journey':e.index||e.active||j.level?'Continue from checkpoint':'Begin expedition'}</span><span>→</span></button><p class="quiet">${progress(j)} / ${maximum(j)} practice sets · ${required(j)} of every type this level · ${practiceGoal(j.level)}</p><button class="evo-preview-link" data-do="evolution-preview">✧ Preview transformation</button></section></div><aside class="partner-plaque"><span class="level-badge">FORM ${j.level} · ${partner().element.toUpperCase()}</span><div class="name">${esc(save.nickname)}</div><small>YOUR CREATURE</small><div class="line"></div><button data-do="rename">Name your creature</button><a class="walk-preview-link" href="partner-preview.html?partner=${partner().id}&level=${Math.min(partner().previewMax,j.level)}" target="_blank" rel="noopener">Movement previews ↗</a></aside>`;}
function lessons(grade=unit().grade){const available=units.filter(u=>u.grade===grade);showModal('Choose your lesson',`<p>Every unit keeps its own creature level, task progress and exact trail checkpoint.</p><div class="grade-tabs">${[5,6,7,8].map(g=>`<button data-do="grade" data-grade="${g}" class="${g===grade?'selected':''}">Grade ${g}<small>${{5:'A1',6:'A1+',7:'A2',8:'A2+'}[g]}</small></button>`).join('')}</div><div class="unit-list">${available.map((u,i)=>{const j=save.journeys[u.id];return`<button class="unit-option ${u.id===save.selected?'selected':''}" data-do="unit" data-unit="${u.id}"><span class="num">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(u.title)}</strong><small>${j?`Level ${j.level} · ${j.completed?'Completed':unlocked(j)+1+' arenas unlocked'}`:'Start a new Level 0 journey'}</small></span></button>`;}).join('')}</div>`);}
function graphicsMenu(){const rows=['explore','task','evolution'].map(phase=>{const m=world.frameMetrics?.snapshot(phase);return `<li>${phase}: ${m?.samples?`${Math.round(m.fps)} fps · p95 ${m.p95.toFixed(1)} ms · ${m.drawCalls} draws · ${Math.round(m.triangles/1000)}k triangles · ${Math.round(m.slow30*100)}% over 33 ms · session worst ${m.sessionWorst.toFixed(1)} ms (${m.samples} recent frames)`:'no play samples yet'}</li>`;}).join('');showModal('Graphics and performance',`<p>Target: 60 fps where practical; stable 30 fps on slower phones. Change settings, play a stretch, then return here to compare observations.</p><div class="graphics-grid">${Object.keys(QUALITY).map(p=>`<button data-do="graphics-preset" data-value="${p}" aria-pressed="${graphics.preset===p}">${p}</button>`).join('')}</div><h3>Resolution cap</h3><div class="graphics-grid">${[.75,1,1.5].map(v=>`<button data-do="graphics-resolution" data-value="${v}" aria-pressed="${graphics.resolution===v}">${v}×</button>`).join('')}</div><button class="secondary wide" data-do="graphics-shadows">Shadows: ${graphics.shadows?'on':'off'}</button><h3>Effects</h3><div class="graphics-grid">${['low','medium','full'].map(v=>`<button data-do="graphics-effects" data-value="${v}" aria-pressed="${graphics.effects===v}">${v}</button>`).join('')}</div><h3>Recent play observations</h3><ul class="frame-observations">${rows}</ul><p>Frame intervals are observed on this browser, with separate exploration, task and evolution samples. These are not GPU timings or a device certification. Menus and hidden-tab gaps are excluded. Test touch, heat and sustained play on real phones.</p><button class="secondary" data-do="graphics-reset">Start a fresh measurement</button><p><a href="partner-preview.html?partner=${partner().id}&level=${journey().level}">Inspect creature animations →</a></p><h3>Device test checklist</h3><p>Play for 15 minutes, include tasks, combat and evolution, then record what you observed. Unchecked items remain untested.</p>${VISUAL_CHECKS.map(([id,label])=>`<label class="device-check">${label}<select data-device-check="${id}"><option value="not-tested">Not tested</option><option value="pass" ${deviceChecks[id]==='pass'?'selected':''}>Pass</option><option value="fail" ${deviceChecks[id]==='fail'?'selected':''}>Needs work</option></select></label>`).join('')}<button class="primary wide" data-do="device-export">Export device report</button>`);}
function saveGraphics(){applyGraphics(world,graphics,typeof devicePixelRatio==='number'?devicePixelRatio:1);world.frameMetrics?.reset();try{localStorage.setItem(GRAPHICS_KEY,JSON.stringify(graphics));}catch{toast('Graphics changed for this session. Device settings could not be saved.');}graphicsMenu();}
function help(){showModal('The Windward Trails',`<p>You are ${esc(save.nickname)}. Use W / ↑ to move forward and S / ↓ to back up. A / ← and D / → turn your creature. Hold forward while turning to follow bends. On phones use the left joystick. Jump with Space or the right button. Cast your ranged elemental attack with J / F or the right attack button. You can cast while airborne. Your elemental shot travels up to 7.5 metres and can be blocked by solid scenery. Watch for the rival’s opening when the shot arrives. Near a rival, your creature faces it automatically: A / D sidestep and W / S approach or retreat. Tap the path to walk there, or use <strong>Follow trail</strong> to approach the next encounter.</p><p>At a fork, follow either branch. Cliff walls separate the routes. Once chosen, your branch stays locked in until the next clearing. Every expedition still includes all twenty activity types. Fruit trees always ask for sentence endings, rune stones for matching, and so on.</p><p>Complete all <strong>20 activity types</strong> in every expedition. Each set has three items. Level ${journey().level} needs ${required(journey())} sets of every type. Guardians at Levels 2, 5 and 10 unlock the next arena or finish the unit.</p><p>Every accepted step and completed task saves automatically. Your unit, arena, chosen branches, unfinished task and walking position return when you continue in this browser. Watch Rumblebud’s amber charge line. Step aside or jump, then strike while it recovers. An air strike can also break its guard before a charge. Brambleguard marks a leaf-slam sector: sidestep, then strike its exposed side or back while its shell is open. Mistcap sends purple rings along the ground: jump over them, approach and interrupt its next burst or strike while its cap is lowered. Watch amber lanes before boulders roll. Shelter behind stones during wind gusts, ride turquoise moving platforms, and follow the green gaps between rising thorns. Strike crystal barriers while their shells are open. Leaf-marked routes are safe; gold ledges offer optional extra coins. Dark stones with glowing cracks crumble after you step on them; keep moving. Collect coins between tasks. Relaxed mode assists jumps at rock edges; Challenge uses manual jumps. Amber plants warn before purple spores burst. Falling returns you to a safe spot and preserves English progress and collected coins. Coins unlock cosmetic wind trails in your journal. Export a backup to move devices.</p><button class="primary wide" data-do="close-modal">Follow the wind →</button>`);}
function trailShopMarkup(){return`<div class="trail-shop"><h3>Wind trails · ${save.wallet?.balance||0} coins</h3><p>Coins unlock cosmetics. English practice grows your creature.</p>${TRAILS.map(t=>`<button data-do="equip-trail" data-trail="${t.id}" class="${save.wallet?.equipped===t.id?'equipped':''}"><i style="background:${t.color}"></i><span>${t.name}</span><b>${save.wallet?.equipped===t.id?'Equipped':save.wallet?.owned.includes(t.id)?'Equip':t.cost+' coins'}</b></button>`).join('')}</div>`;}
function trailShop(){showModal('Wind trails',trailShopMarkup());}
function journal(){const j=journey(),e=state();showModal('Journey journal',`<p>${esc(unit().title)} · Grade ${unit().grade} · Form ${j.level}</p><p>${esc(AREAS[save.area].name)} · ${esc(CHAPTERS[Math.min(4,Math.floor(e.index/4))][0])}<br><strong>Next:</strong> ${esc(activeNode(e)?.object||'Choose a path at the fork')}</p><div class="milestone-summary"><strong>${e.index} / 20 milestones this expedition</strong><small>${e.checkpoint?`Last saved: ${esc(activity(e.checkpoint.type).object)}`:'No completed encounter yet'}</small></div><div class="trail-checklist">${ACTIVITIES.map(a=>`<div><span>${a.symbol} ${esc(a.label)}</span><b>${j.sets[a.id]} / ${required(j)}</b></div>`).join('')}</div><p>${Math.max(0,maximum(j)-progress(j))} practice sets remain at this level. Continue across sessions; each milestone saves.</p><p>Unit bank: ${unit().vocabulary.length} vocabulary entries · ${unit().questions.length} question records. More demanding items are preferred when exposure is equal; all unit content stays eligible for review.</p><p>${j.stats.correct} accepted steps · ${j.stats.mistakes} corrections · ${j.stats.hints} hints</p><button class="secondary" data-do="trails">Wind trails · ${save.wallet?.balance||0} coins →</button><button class="secondary wide" data-do="graphics">Graphics and performance</button>${typeof navigator!=='undefined'&&typeof navigator.vibrate==='function'?`<button class="secondary wide" data-do="haptics">Vibration: ${save.haptics===false?'off':'on'}</button>`:''}<div class="journal-actions"><button class="secondary" data-do="export">Export backup</button><button class="secondary" data-do="import">Import backup</button>${j.level?'<button class="secondary" data-do="evolution-replay-earned">Replay latest evolution</button>':''}<button class="secondary" data-do="restart">Restart this unit</button></div>`);}
async function enter(){locked=true;syncWorld();await world.loadForm(journey().level);screen='play';locked=false;document.body.classList.add('playing');world.setView(false);world.paused=false;persist();if(state().battle){showBattle();return;}if(state().active){task=state().active;openTaskView();return;}renderPlay();if(!save.tutorial){save.tutorial=true;persist();toast('Choose a branch. Move with the joystick or WASD; jump with the Jump button or Space. Each discovery teaches its own action.');}}
function renderPlay(){screen='play';task=null;resultCard=false;feedbackText='';nearId='';document.body.classList.remove('guardian-choice');const e=state(),node=activeNode(e),chapter=Math.min(4,Math.floor(e.index/4)),fork=!e.choices[chapter]&&e.index<20;$('#ui').innerHTML=`<button class="play-status" data-do="journal" aria-label="${esc(save.nickname)} level ${journey().level}, ${e.index} of 20 milestones. Open journey journal."><img src="${partnerPortrait(partner().id,journey().level)}" alt=""><span>Lv. ${journey().level} · ${e.index}/20</span><b>◉ <span id="coin-count">${coinText()}</span></b></button><div class="play-dock"><div class="traversal-hint" id="traversal-hint">${fork?'Choose a path with the arrows or joystick.':''}</div><div class="joystick" id="joystick" aria-label="Move your creature"><div id="joystick-thumb"></div></div>${fork?`<div class="fork-actions"><button data-do="branch" data-side="left" aria-label="Left: ${esc(CHAPTERS[chapter][1])}. ${esc(firstOnBranch('left'))}">↖<small>Left</small></button><button data-do="branch" data-side="right" aria-label="Right: ${esc(CHAPTERS[chapter][2])}. ${esc(firstOnBranch('right'))}">↗<small>Right</small></button></div>`:`<button class="attack-button" id="attack-button" style="--cast-color:${elementalAttack(partner().id).color}" data-do="attack" aria-label="${elementalAttack(partner().id).name}: ranged elemental attack">✦<small>${elementalAttack(partner().id).label}</small></button><button class="jump-button" id="jump-button" data-do="jump" aria-label="Jump">↑<small>JUMP</small></button><div class="context-action" id="context-action"><small id="context-name"></small><button id="context-button" data-do="follow" aria-label="Follow trail to the next discovery">›<small>Follow</small></button></div>`}</div>`;$('#task-layer').innerHTML='';joystick();}
function firstOnBranch(side){const e=state(),c=Math.floor(e.index/4),copy={...e,choices:e.choices.slice()};copy.choices[c]=side;return activity(currentType(copy)).object+' first';}
let disposeStick=null;function joystick(){disposeStick?.();const handlers=[bindStick($('#joystick'),$('#joystick-thumb'),(x,z)=>world.setInput(x,z),()=>persist(),window,document),bindActionButton($('#jump-button'),()=>world.jump(),window,document),bindActionButton($('#attack-button'),()=>world.attack?.(),window,document)];disposeStick=()=>handlers.forEach(dispose=>dispose());}
function branch(side){const e=state();if(!chooseBranch(e,side))return;persist();world.refresh();renderPlay();toast(`Following ${CHAPTERS[Math.floor(e.index/4)][side==='left'?1:2]}. Branch choice saved.`);nav.approach();}
