function leave(){gameAudio.silence();gameAudio.reading=false;if(!world)return;world.keys?.clear();world.setInput(0,0);nav.stop();persist();window.speechSynthesis?.cancel?.();evoStop?.();evoStop=null;}
window.addEventListener('pagehide',leave);window.addEventListener('beforeunload',()=>{if(world)persist();});document.addEventListener('visibilitychange',()=>{if(document.hidden)leave();else if(evoState?.started&&world.evolution&&!world.evolution.resolved)playEvolutionSound();});
async function boot(){try{const data=await fetch('data/expedition-language.json').then(r=>{if(!r.ok)throw Error('Language data missing');return r.json();});units=data.units;try{const current=JSON.parse(localStorage.getItem(STORE)||'null');if(validSave(current,units))save=current;else{const legacy=JSON.parse(localStorage.getItem(LEGACY_STORE)||'null');if(validLegacy(legacy,units))save=migrate(legacy,units);}}catch{toast('A fresh trail is ready. You can import a journey backup.');}save=upgradePartners(upgradeTraversalSave(save));save.area=Math.min(save.area,unlocked(journey()));const e=state();nav=new TrailNavigator(e,interact);configureTravel();nav.setLevel(journey().level);nav.restore(e.position);nav.heading=e.heading;world=new TrailWorld($('#world'),interact,nav);world.partner=partner().id;world.elementColor=partner().color;world.onFrame=frame;if(typeof location!=='undefined'&&/[?&]debug\b/.test(location.search||''))window.maxima={world,nav,get save(){return save;},state,persist,renderPlay};if(world.renderer)applyGraphics(world,graphics,typeof devicePixelRatio==='number'?devicePixelRatio:1);await world.loadForm(journey().level);await home();soundUpdate();persist();$('#load-note').classList.add('hidden');}catch(error){console.error(error);$('#load-note').classList.add('hidden');$('#ui').innerHTML='<section class="error-box"><div class="eyebrow">MAXIMA</div><h1>3D graphics could not start.</h1><p>This browser could not start the 3D world or load its local game files. Try a current browser with WebGL graphics acceleration.</p><p>Your saved journeys are preserved on this device.</p><button class="primary" onclick="location.reload()">Retry</button></section>';}}
boot();
